using System.Net;
using System.Text;
using System.Text.Json.Nodes;
using BridgeTranslate.Core;
int passed=0;void Check(bool condition,string message){if(!condition)throw new Exception(message);passed++;Console.WriteLine("PASS "+message);}
var config=new ApiSettings{Endpoint="https://api.example.test/v1",Model="test",Key="TEST_KEY"};
Check(TranslationRules.Endpoint(config).AbsolutePath=="/v1/chat/completions","Chat base endpoint");
foreach(var proto in new[]{"responses","anthropic","gemini"}){config.Protocol=proto;Check(TranslationRules.Endpoint(config).Scheme=="https","protocol endpoint "+proto);}config.Protocol="chat";
foreach(var invalid in new[]{"http://remote.test/v1","https://u:secret@remote.test/v1","https://remote.test/v1?api_key=secret","https://claude.ai"}){config.Endpoint=invalid;try{TranslationRules.Endpoint(config);throw new Exception("accepted invalid");}catch(InvalidOperationException){Check(true,"reject invalid endpoint");}}config.Endpoint="https://api.example.test/v1";
var source="# Read `fn()`\n\n```py\nsecret_code()\n```\n\n$$\nx^2=1\n$$\n\nA [link](https://secret.test) and ![private](https://img.test/a.png).";
var protectedText=new ProtectedText(source);foreach(var value in new[]{"fn()","secret_code()","x^2","secret.test","img.test"})Check(!protectedText.Text.Contains(value),"protect "+value);Check(protectedText.Restore(protectedText.Text)==source,"exact protected round trip");
try{protectedText.Restore("missing");throw new Exception("missing placeholder accepted");}catch(InvalidOperationException){Check(true,"reject lost placeholders");}
var parts=MarkdownSegments.Split(source,false);Check(string.Concat(parts.Select(x=>x.Text))==source,"segmentation round trip");Check(!parts[^1].Closed,"streaming last paragraph waits");Check(MarkdownSegments.Split("```js\nunfinished",false)[0].Keep,"unfinished code stays local");
Check(TranslationRules.HasHan("你好𠀀")&&!TranslationRules.HasHan("Hello"),"Han detection includes extension plane");
var parsed=SessionParser.Parse("""{"type":"assistant","uuid":"u","sessionId":"s","message":{"id":"m","role":"assistant","content":[{"type":"thinking","thinking":"DO_NOT_SEND"},{"type":"text","text":"Answer."},{"type":"tool_use","input":{"cmd":"PRIVATE"}}],"stop_reason":"end_turn"}}""");Check(parsed?.Text=="Answer."&&parsed.Complete,"only assistant text parsed");Check(SessionParser.Parse("""{"type":"user","message":{"content":"private"}}""")==null,"user records skipped");Check(SessionParser.Parse("{broken")==null,"partial JSON ignored");
var state=new ReplyState{Id="r"};state.Update("First.\n\nTail",false);state.Translations["First.\n\n"]="第一段。\n\n";Check(state.Render("bilingual").Contains("First.\n\n第一段。"),"bilingual below source");state.Update("First.\n\nTail grows.",false);Check(state.Translations.Count==1,"append preserves previous translation");state.Update("Rewritten.",true);Check(state.Translations.Count==0,"revision invalidates stale translation");
var html=MarkdownDisplay.ToHtml("# Title\n\n<script>alert(1)</script>\n\nMath \\(x^2\\) and $y$.\n\n```js\nconst x = '$code';\n```\n\n![img](https://img.test/p.png)\n\n| A | B |\n|---|---|\n| 1 | 2 |");Check(!html.Contains("<script>"),"raw HTML disabled");Check(html.Contains("data-tex=\"x^2\""),"TeX survives Markdown renderer");Check(html.Contains("data-source=\"https://img.test/p.png\"")&&!html.Contains("src=\"https://img.test"),"remote images require explicit load");Check(html.Contains("<table>"),"Markdown table render");
var handler=new FakeHandler();using var http=new HttpClient(handler);using var api=new TranslationClient(http);var result=await api.TranslateAsync(config,"Read `fn()` and $x=2$.","zh",CancellationToken.None);Check(result.Contains("fn()")&&result.Contains("x=2"),"model result restores code/math");Check(!handler.LastBody.Contains("fn()")&&!handler.LastBody.Contains("x=2"),"code/math absent from API request");
handler.Error=true;try{await api.TranslateAsync(config,"source","zh",CancellationToken.None);throw new Exception("error accepted");}catch(InvalidOperationException ex){Check(ex.Message.Contains("401")&&!ex.Message.Contains("PRIVATE"),"provider error does not leak body");}handler.Error=false;
try{await api.TranslateAsync(config,"hello","en",CancellationToken.None);throw new Exception("Han result accepted");}catch(InvalidOperationException){Check(true,"English result with Han rejected");}
var file=System.IO.Path.GetTempFileName();try{var follower=new SessionFollower();File.WriteAllText(file,"");follower.Select(file,true);var line="""{"type":"assistant","message":{"id":"test","content":[{"type":"text","text":"回答"}]}}""";var bytes=Encoding.UTF8.GetBytes(line+"\n");await File.WriteAllBytesAsync(file,bytes[..^3]);Check((await follower.PollAsync(CancellationToken.None)).Count==0,"partial UTF8 JSONL is buffered");await using(var f=new FileStream(file,FileMode.Append)){await f.WriteAsync(bytes[^3..]);}Check((await follower.PollAsync(CancellationToken.None)).Single().Text=="回答","split UTF8 line recovered");Check((await follower.PollAsync(CancellationToken.None)).Count==0,"no repeat on unchanged transcript");follower.Clear();Check(follower.Path==null,"file follower disconnects");}finally{File.Delete(file);}
if(args.Length==2&&args[0]=="--render")File.WriteAllText(args[1],html);
Console.WriteLine($"All {passed} checks passed.");
class FakeHandler:HttpMessageHandler{public string LastBody="";public bool Error;protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){LastBody=await request.Content!.ReadAsStringAsync(token);if(Error)return new(HttpStatusCode.Unauthorized){Content=new StringContent("PRIVATE_KEY_AND_SOURCE")};var d=JsonNode.Parse(LastBody)!;var text=d["messages"]![1]!["content"]!.ToString();return new(HttpStatusCode.OK){Content=new StringContent(new JsonObject{["choices"]=new JsonArray(new JsonObject{["message"]=new JsonObject{["content"]="中文："+text},["finish_reason"]="stop"})}.ToJsonString())};}}
